from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, RFC3339DateTime, SdkBaseModel
from .enums.source_api_association_status import SourceApiAssociationStatusOrStr
from .source_api_association_config import SourceApiAssociationConfig, SourceApiAssociationConfigDict


class SourceApiAssociation(SdkBaseModel):
    association_id: Optional[str] = Field(default=UNSET, alias="associationId")
    """The ID generated by the AppSync service for the source API association."""

    association_arn: Optional[str] = Field(default=UNSET, alias="associationArn")
    """The Amazon Resource Name (ARN) of the source API association."""

    source_api_id: Optional[str] = Field(default=UNSET, alias="sourceApiId")
    """The ID of the AppSync source API."""

    source_api_arn: Optional[str] = Field(default=UNSET, alias="sourceApiArn")
    """The Amazon Resource Name (ARN) of the AppSync source API."""

    merged_api_arn: Optional[str] = Field(default=UNSET, alias="mergedApiArn")
    """The Amazon Resource Name (ARN) of the AppSync Merged API."""

    merged_api_id: Optional[str] = Field(default=UNSET, alias="mergedApiId")
    """The ID of the AppSync Merged API."""

    description: Optional[str] = UNSET
    """The description field."""

    source_api_association_config: Optional[SourceApiAssociationConfig] = Field(
        default=UNSET, alias="sourceApiAssociationConfig"
    )
    source_api_association_status: Optional[SourceApiAssociationStatusOrStr] = Field(
        default=UNSET, alias="sourceApiAssociationStatus"
    )
    """The state of the source API association."""

    source_api_association_status_detail: Optional[str] = Field(default=UNSET, alias="sourceApiAssociationStatusDetail")
    """The detailed message related to the current state of the source API association."""

    last_successful_merge_date: Optional[RFC3339DateTime] = Field(default=UNSET, alias="lastSuccessfulMergeDate")
    """The datetime value of the last successful merge of the source API association. The result will be in UTC format
    and your local time zone."""


class SourceApiAssociationDict(TypedDict):
    association_id: NotRequired[str]
    association_arn: NotRequired[str]
    source_api_id: NotRequired[str]
    source_api_arn: NotRequired[str]
    merged_api_arn: NotRequired[str]
    merged_api_id: NotRequired[str]
    description: NotRequired[str]
    source_api_association_config: NotRequired[SourceApiAssociationConfigDict]
    source_api_association_status: NotRequired[SourceApiAssociationStatusOrStr]
    source_api_association_status_detail: NotRequired[str]
    last_successful_merge_date: NotRequired[RFC3339DateTime]
